{"path": "styles.css", "content": "/* Base styles */
:root {
  --bg-color: #ffffff;
  --text-color: #000000;
  --link-color: #007BFF;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
}

/* Dark mode styles */
.dark-mode {
  --bg-color: #121212;
  --text-color: #ffffff;
  --link-color: #007BFF;
}

/* Navigation styles */
.site-header {
  background-color: var(--bg-color);
  padding: 1rem 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.nav-list {
  list-style: none;
  display: flex;
  gap: 1.5rem;
  margin: 0;
  padding: 0;
}

.nav-list a {
  text-decoration: none;
  color: var(--link-color);
  transition: color 0.3s;
}

.nav-list a:hover {
  color: #0056b3;
}

/* Form styles */
#appointment-form {
  display: grid;
  gap: 1rem;
  margin-top: 2rem;
}

/* Gallery styles */
#gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-top: 2rem;
}

.gallery-item {
  text-align: center;
}

.gallery-item img {
  width: 100%;
  height: auto;
  border-radius: 8px;
}

/* Footer styles */
.site-footer {
  background-color: var(--bg-color);
  color: var(--text-color);
  padding: 2rem 2rem;
  text-align: center;
}

/* Theme toggle styles */
#theme-toggle {
  background: none;
  border: none;
  color: var(--link-color);
  cursor: pointer;
  font-size: 1rem;
  padding: 0.5rem 1rem;
  transition: background 0.3s;
}

#theme-toggle:hover {
  background-color: #f0f0f0;
}

/* Dark mode overrides */
.dark-mode .site-header {
  background-color: var(--bg-color);
}

.dark-mode .site-footer {
  background-color: var(--bg-color);
}

.dark-mode #theme-toggle {
  color: #007BFF;
}

/* Input styles */
input, select, textarea {
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 4px;
}

input:invalid, select:invalid, textarea:invalid {
  border-color: red;
}

/* Button styles */
button {
  background-color: #007BFF;
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.3s;
}

button:hover {
  background-color: #0056b3;
}

/* Accessibility focus styles */
:focus {
  outline: 2px solid #007BFF;
  outline-offset: 2px;
}

/* Responsive design */
@media (max-width: 600px) {
  .nav-list {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* Table styles */
#hours-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1rem;
}

#hours-table th, #hours-table td {
  border: 1px solid #ccc;
  padding: 0.5rem;
}

#hours-table th {
  background-color: #f0f0f0;
}

#hours-table tr:nth-child(even) {
  background-color: #f9f9f9;
}

/* News styles */
#news-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-top: 2rem;
}

.news-article {
  text-align: center;
}

.news-article img {
  width: 100%;
  height: auto;
  border-radius: 8px;
}

.news-article h2 {
  margin: 0.5rem 0 0.25rem 0;
}

.news-article time {
  color: #666;
}

.news-article a {
  display: inline-block;
  margin-top: 0.5rem;
  color: var(--link-color);
  text-decoration: none;
}

.news-article a:hover {
  text-decoration: underline;
}

/* Form labels */
label {
  display: block;
  margin-top: 1rem;
}

/* Error states */
input:invalid, select:invalid, textarea:invalid {
  border-color: red;
}

/* Checkbox styles */
label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Responsive form */
@media (max-width: 600px) {
  #appointment-form {
    grid-template-columns: 1fr;
  }
}

/* Gallery responsiveness */
@media (max-width: 600px) {
  #gallery {
    grid-template-columns: 1fr;
  }
}

/* News responsiveness */
@media (max-width: 600px) {
  #news-list {
    grid-template-columns: 1fr;
  }
}

/* Table responsiveness */
@media (max-width: 600px) {
  #hours-table {
    display: block;
    margin: 1rem auto;
  }
}

/* Footer responsiveness */
@media (max-width: 600px) {
  .site-footer {
    text-align: left;
  }
}

/* Header responsiveness */
@media (max-width: 600px) {
  .site-header {
    flex-direction: column;
    align-items: flex-start;
