/* Base styles */
body {
  font-family: Arial, sans-serif;
  line-height: 1.6;
  color: #333;
  background-color: #fff;
  transition: background-color 0.3s, color 0.3s;
}

/* Dark theme */
body.dark-theme {
  background-color: #121212;
  color: #f5f5f5;
}

/* Light theme */
body.light-theme {
  background-color: #fff;
  color: #333;
}

/* Navigation styles */
.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  background-color: #f8f8f8;
  border-bottom: 1px solid #ccc;
}

/* Navigation links */
.nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: 1.5rem;
}

.nav-list li a {
  text-decoration: none;
  color: #333;
  transition: color 0.3s;
}

.nav-list li a:hover {
  color: #007BFF;
}

/* Toggle button */
#theme-toggle {
  background: none;
  border: none;
  color: #007BFF;
  font-size: 1rem;
  cursor: pointer;
  padding: 0.5rem 1rem;
  transition: background 0.3s;
}

body.dark-theme #theme-toggle {
  color: #f5f5f5;
}

#theme-toggle:hover {
  background-color: #007BFF;
  color: #fff;
}

/* Gallery styles */
#gallery {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 2rem;
}

.gallery-item {
  flex: 1 1 calc(25% - 1.5rem);
  min-width: 200px;
  text-align: center;
}

.gallery-item img {
  width: 100%;
  height: auto;
  display: block;
}

.gallery-item figcaption {
  margin-top: 0.5rem;
  font-size: 0.9rem;
  color: #555;
}

/* Form styles */
#appointment-form {
  display: grid;
  gap: 1rem;
  max-width: 600px;
  margin: 2rem auto;
}

#appointment-form label {
  font-weight: bold;
}

#appointment-form input, #appointment-form select, #appointment-form textarea {
  padding: 0.5rem;
  font-size: 1rem;
}

#appointment-form button {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  background-color: #007BFF;
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background-color 0.3s;
}

#appointment-form button:hover {
  background-color: #0056b3;
}

/* Table styles */
#hours-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1rem;
}

#hours-table th, #hours-table td {
  border: 1px solid #ccc;
  padding: 0.5rem;
}

#hours-table th {
  background-color: #f0f0f0;
}

/* Contact form styles */
#contact-form {
  display: grid;
  gap: 1rem;
  max-width: 600px;
  margin: 2rem auto;
}

#contact-form label {
  font-weight: bold;
}

#contact-form input, #contact-form textarea {
  padding: 0.5rem;
  font-size: 1rem;
}

#contact-form button {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  background-color: #007BFF;
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background-color 0.3s;
}

#contact-form button:hover {
  background-color: #0056b3;
}

/* News styles */
#news-list {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 2rem;
}

.news-article {
  flex: 1 1 calc(33% - 1.5rem);
  min-width: 200px;
  text-align: center;
}

.news-article img {
  width: 100%;
  height: auto;
  display: block;
}

.news-article h2 {
  margin: 0.5rem 0 0.25rem;
}

.news-article time {
  font-size: 0.9rem;
  color: #555;
}

.news-article a {
  display: inline-block;
  margin-top: 0.5rem;
  color: #007BFF;
  text-decoration: none;
}

.news-article a:hover {
  text-decoration: underline;
}

/* Footer styles */
.site-footer {
  text-align: center;
  padding: 2rem 1rem;
  background-color: #f8f8f8;
  border-top: 1px solid #ccc;
}

.site-footer address {
  margin: 0;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .nav-list {
    flex-direction: column;
    align-items: flex-start;
  }

  #gallery {
    flex-direction: column;
    align-items: center;
  }

  #news-list {
    flex-direction: column;
    align-items: center;
  }
}

@media (max-width: 480px) {
  .nav-list {
    gap: 1rem;
  }

  #gallery {
    margin-top: 1rem;
  }

  #news-list {
    margin-top: 1rem;
  }
}

